public class RetrieveInputExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a number: ");

        int num = 0;

        while (true) {
            try {
                num = scanner.nextInt();
                break;
            } catch (InputMismatchException e) {
                System.out.println("Invalid input! Please enter an integer.");
                scanner.nextLine(); // Consume remaining characters on the line
            }
        }

        int result = calculateResult(num);
        System.out.printf("The result is: %.2f", (double) result / 100);

        scanner.close();
    }

    private static int calculateResult(int num) {
        return (num * 100) + (9 * Math.abs(num));
    }
}
```

