2. Define functions to extract data from each file format:

```R
# Function to extract data from XML files
extract_xml <- function(filepath) {
  xml_data <- read_xml(filepath)
  data <- xml_data %>%
    xml_nodes("item") %>%
    xml_attr("date") %>%
    as.Date(format = "%Y-%m-%d", tz = "UTC") %>%
    xml_text() %>%
    str_c(collapse = "\n") %>%
    str_replace_all("(<.*?>)", "") %>%
    str_trim()
  return(list(date = data$date, description = data$description))
}

# Function to extract data from CSV files
extract_csv <- function(filepath) {
  csv_data <- read.csv(filepath, header = TRUE)
  return(list(date = as.Date(csv_data$date), description = csv_data$description))
}

# Function to extract data from JSON files
extract_json <- function(filepath) {
  json_data <- fromJSON(filepath)
  return(list(date = json_data$date, description = json_data$description))
}
```

