1. First, make sure that you have installed the `Microsoft.IdentityModel.Tokens` package. You can do this by running the following command in the Package Manager Console (PMC):

   ```
   Install-Package Microsoft.IdentityModel.Tokens
   ```

2. In your WebAPI controller, create a method to extract the user name from the JWT token. Here's an example:

   ```csharp
   using System;
   using System.IdentityModel.Tokens.Jwt;
   using System.Security.Claims;
   using System.Text;
   using Microsoft.IdentityModel.Tokens;

   namespace MyWebApi.Controllers
   {
       [Route("api/[controller]")]
       public class ValuesController : ControllerBase
       {
           private readonly SymmetricSecurityKey _signingKey;
           private readonly SigningCredentials _signingCredentials;

           public ValuesController()
           {
               _signingKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes("supersecret_key"));
               _signingCredentials = new SigningCredentials(_signingKey, SecurityAlgorithms.HmacSha256);
           }

           // This method retrieves the user name from the JWT token
           [HttpGet("getusernamefromtoken")]
           public string GetUsernameFromToken()
           {
               var token = Request.Headers["Authorization"].Split(" ")[1];
               var tokenHandler = new JwtSecurityTokenHandler();
               var securityToken = tokenHandler.ReadJwtToken(token);
               return securityToken.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
           }
       }
   }
   ```

3. In the constructor of the `ValuesController`, initialize the symmetric key and signing credentials used for signing the JWT tokens.

4. The `GetUsernameFromToken` action reads the authorization header from the request, splits it into two parts, and passes the second part (the actual JWT token) to the `JwtSecurityTokenHandler`. This handler parses the token, returns a `SecurityToken`

