Here's an example of simulating natural selection using MATLAB:

```matlab
% Initialize populations with different traits
populationSize = 1000;
phenotypeA = rand(1, populationSize); % Trait A with values between 0 and 1
phenotypeB = rand(1, populationSize); % Trait B with values between 0 and 1
survivalFitnessA = 0.8 * phenotypeA; % Fitness function for trait A, where 0.8 is the survival rate
survivalFitnessB = 0.9 * phenotypeB; % Fitness function for trait B, where 0.9 is the survival rate

% Simulate natural selection over multiple generations
generation = 1;
while generation <= 10
    % Calculate fitness scores based on survival rates
    fitnessScoreA = survivalFitnessA(1:populationSize);
    fitnessScoreB = survivalFitnessB(1:populationSize);

    % Select parents randomly with probability proportional to fitness scores
    parentA = floor(cumsum(fitnessScoreA) * populationSize) + 1;
    parentB = floor(cumsum(fitnessScoreB) * populationSize) + 1;

    % Calculate offspring traits by averaging parent traits
    childA = (phenotypeA(parentA) + phenotypeA(parentB)) / 2;
    childB = (phenotypeB(parentA) + phenotypeB(parentB)) / 2;

    % Update populations with new offspring
    [populationA, populationB] = sort(vertcat(childA, childB), 'descend');
    populationSize = min(populationSize * 1.01, length(populationA)); % Increase population size slightly

    % Display statistics after each generation
    fprintf('Generation %d:\n', generation)
    fprintf('Average trait value for A: %.4f\n', mean(populationA))
    fprintf('Average trait value for B: %.4f\n', mean(populationB))
    generation = generation + 1;
end
```

