// Rust implementation of `is_even` with nested `if` statements
 fn is_even(n: i32) -> bool {
     match n {
         0 => true,
         1 | 3 | 5 | 7 | 9 => false,
         2 | 4 | 6 | _ => unimplemented!(),
     }
 }

 // More idiomatic and concise Rust implementation using bitwise operations
 fn is_even_bitwise(n: i32) -> bool {
     n & 1 == 0
 }

 // Using a loop for better readability
 fn is_even_loop(n: i32) -> bool {
     let mut divisor = 2;
     while n > divisor {
         divisor *= 2;
     }
     divisor == n || divisor == n - 1
 }

 // Using recursion for an elegant solution
 fn is_even_recursive(n: i32) -> bool {
     match n % 2 {
         0 => true,
         _ => is_even_recursive(n - 1),
     }
