```php
function getLoyalCustomers($productId)
{
    $sql = "SELECT DISTINCT c.customer_id, c.first_name, c.last_name, COUNT(o.order_id) AS num_orders
             FROM orders o
             JOIN customers c ON o.customer_id = c.customer_id
             WHERE o.product_id = :product_id AND o.created_at >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)
             GROUP BY c.customer_id
             HAVING num_orders >= 3 AND num_orders % 7 = 0";
    $stmt = $this->pdo->prepare($sql);
    $stmt->bindParam(':product_id', $productId, PDO::PARAM_INT);
    $stmt->execute();
    return $stmt->fetchAll();
}
