To implement a function in Go to detect whether a given sentence contains a double negative or not, we need to follow these steps:

1. Define a list of negative words that could potentially be part of a double negative.
2. Check if the sentence contains any of those negative words.
3. If it does, then check if there is an occurrence of "not" immediately following one of those negative words.
4. If both conditions are true, return a message indicating that the sentence contains a double negative.

Here's the implementation:

```go
package main

import (
	"fmt"
	"strings"
)

// List of negative words
var negatives = []string{"n't", "no", "nor", "none"}

func hasDoubleNegative(sentence string) bool {
	for _, negative := range negatives {
		if strings.Contains(sentence, negative) && strings.Contains(sentences[strings.Index(sentence, negative):], "not") {
			return true
		}
		// Check for case sensitivity
		if strings.Contains(sentence, negative[0:len(negative)-2]) && strings.Contains(sentences[strings.Index(sentence, negative[0:len(negative)-2]):], "not") {
			return true
		}
		// Check for contractions with "n't"
		if strings.Contains(sentence, "aren't") || strings.Contains(sentence, "isn't") || strings.Contains(sentence, "wasn't") || strings.Contains(sentence, "can't") || strings.Contains(sentence, "won't") {
			return false // Contractions with "n't" don't count as double negatives
		}
	}
	return false
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if hasDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence doesn't contain a double negative.")
	}
}
